from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

OUT='output/FAIR_PLAY_TP3_estructura_sidebar.pdf'
W,H=A4
NOCHE=colors.HexColor('#051014'); CARBON=colors.HexColor('#2E2F2F'); PIZARRA=colors.HexColor('#828A95'); SALVIA=colors.HexColor('#708D81'); PAPEL=colors.HexColor('#FCFCFC')
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='CoverTitle',parent=s['Title'],fontName='Helvetica-Bold',fontSize=27,leading=31,textColor=PAPEL,spaceAfter=10))
s.add(ParagraphStyle(name='CoverSub',parent=s['Normal'],fontName='Helvetica',fontSize=11,leading=16,textColor=colors.HexColor('#DDE5E1')))
s.add(ParagraphStyle(name='H1FP',parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=18,leading=23,textColor=NOCHE,spaceAfter=8))
s.add(ParagraphStyle(name='H2FP',parent=s['Heading2'],fontName='Helvetica-Bold',fontSize=11,leading=14,textColor=SALVIA,spaceBefore=8,spaceAfter=4))
s.add(ParagraphStyle(name='BodyFP',parent=s['BodyText'],fontName='Helvetica',fontSize=9.3,leading=13.5,textColor=CARBON,spaceAfter=5))
s.add(ParagraphStyle(name='SmallFP',parent=s['BodyText'],fontName='Helvetica',fontSize=8,leading=11,textColor=PIZARRA))
s.add(ParagraphStyle(name='CenterSmall',parent=s['BodyText'],fontName='Helvetica-Bold',fontSize=8.2,leading=10.5,alignment=TA_CENTER,textColor=CARBON))
s.add(ParagraphStyle(name='SidebarItem',parent=s['BodyText'],fontName='Helvetica-Bold',fontSize=9.2,leading=12,textColor=PAPEL))
s.add(ParagraphStyle(name='SidebarDesc',parent=s['BodyText'],fontName='Helvetica',fontSize=7.6,leading=10.2,textColor=colors.HexColor('#DDE5E1')))

def footer(c,doc):
    c.saveState(); c.setStrokeColor(colors.HexColor('#D9DEDC')); c.line(18*mm,14*mm,W-18*mm,14*mm); c.setFont('Helvetica',7.5); c.setFillColor(PIZARRA); c.drawString(18*mm,8.5*mm,'FAIR PLAY · TP3 · Arquitectura de Figma'); c.drawRightString(W-18*mm,8.5*mm,str(doc.page)); c.restoreState()
def cover(c,doc):
    c.saveState(); c.setFillColor(NOCHE); c.rect(0,0,W,H,fill=1,stroke=0); c.setFillColor(SALVIA); c.rect(18*mm,H-38*mm,16*mm,3*mm,fill=1,stroke=0); c.setFillColor(PAPEL); c.setFont('Helvetica-Bold',10); c.drawString(18*mm,H-49*mm,'FAIR PLAY'); c.setFillColor(colors.HexColor('#DDE5E1')); c.setFont('Helvetica',8); c.drawString(18*mm,H-55*mm,'Manual de organización para el tercer TP'); c.restoreState()

story=[Spacer(1,57*mm),Paragraph('Sidebar recomendada<br/>para Figma',s['CoverTitle']),Paragraph('Sistema de páginas para ordenar informe, prototipos web y tótem sin perder la narrativa del evento.',s['CoverSub']),Spacer(1,35*mm),Paragraph('Idea rectora',ParagraphStyle('label',parent=s['CoverSub'],fontName='Helvetica-Bold',textColor=SALVIA,fontSize=9)),Spacer(1,3*mm),Paragraph('Atracción → participación → revelación → reflexión',ParagraphStyle('quote',parent=s['CoverSub'],fontName='Helvetica-Bold',fontSize=15,leading=20,textColor=PAPEL)),Spacer(1,32*mm),Paragraph('Guía práctica · versión 1.0 · 30/09/2026',s['CoverSub']),PageBreak()]
story += [Paragraph('La estructura que conviene construir',s['H1FP']),Paragraph('El archivo actual funciona como un informe extenso en una única página. Para TP3 conviene separar el trabajo por intención: primero el contexto, después las decisiones y finalmente las pantallas navegables.',s['BodyFP'])]
items=[('00 · PORTADA','Nombre del proyecto, integrantes, materia, etapa y versión.'),('01 · CONTEXTO FAIR PLAY','Problema, objetivo, público principal, narrativa del evento y recorrido de tres zonas.'),('02 · REFERENTES DIGITALES','Sitios y experiencias analizadas; captura, enlace, hallazgo y decisión que inspira.'),('03 · REVISIÓN DE MARCA','Logo, paleta, tipografías, tono, usos, accesibilidad cromática y adaptaciones para pantalla.'),('04 · ARQUITECTURA Y CONTENIDOS','Inventario, mapa del sitio, jerarquía y reglas de voz y tono.'),('05 · FLOWS','Task-flow, user-flow y wireflow, con inicio, decisiones, estados y final.'),('06 · WIREFRAMES WEB','Estructuras en baja fidelidad del sitio.'),('07 · UI KIT COMPARTIDO','Tokens, colores, tipografía, botones, cards, navegación, iconos y estados.'),('08 · SITIO WEB · MOCKUPS','Pantallas de alta fidelidad y prototipo navegable del sitio público.'),('09 · TÓTEM · MOCKUPS','Pantallas de alta fidelidad y prototipo para la interacción presencial.'),('10 · HEURÍSTICAS','Evaluación separada de web y tótem, con hallazgo, severidad y propuesta.'),('11 · TESTEOS','Guion, tareas, perfiles, observaciones, evidencias y síntesis.'),('12 · ITERACIÓN FINAL','Antes/después, decisiones de mejora y prototipo validado.')]
data=[[Paragraph('Página',s['CenterSmall']),Paragraph('Qué debe contener',s['CenterSmall'])]]+[[Paragraph(a,s['BodyFP']),Paragraph(b,s['BodyFP'])] for a,b in items]
t=Table(data,colWidths=[50*mm,125*mm],repeatRows=1); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NOCHE),('TEXTCOLOR',(0,0),(-1,0),PAPEL),('GRID',(0,0),(-1,-1),0.35,colors.HexColor('#D9DEDC')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('BACKGROUND',(0,1),(-1,-1),PAPEL)])); story += [t,PageBreak()]
story += [Paragraph('Cómo nombrar y ordenar las zonas',s['H1FP']),Paragraph('Usen números de dos dígitos para que las páginas mantengan el orden. Usen mayúsculas solo en la etiqueta de la sección y nombres concretos en cada pantalla.',s['BodyFP'])]
sidebar=[[Paragraph('SIDEBAR DEL ARCHIVO',s['SidebarItem']),Paragraph('FUNCIÓN',s['SidebarItem'])],[Paragraph('00 · PORTADA',s['SidebarItem']),Paragraph('Entrada y control de versión',s['SidebarDesc'])],[Paragraph('01–04 · FUNDAMENTOS',s['SidebarItem']),Paragraph('Qué problema resolvemos y con qué criterios',s['SidebarDesc'])],[Paragraph('05 · FLOWS',s['SidebarItem']),Paragraph('Cómo se mueve la persona dentro de cada producto',s['SidebarDesc'])],[Paragraph('06–07 · SISTEMA',s['SidebarItem']),Paragraph('Estructura visual y reglas reutilizables',s['SidebarDesc'])],[Paragraph('08 · WEB',s['SidebarItem']),Paragraph('Producto público previo al evento',s['SidebarDesc'])],[Paragraph('09 · TÓTEM',s['SidebarItem']),Paragraph('Producto rápido durante el evento',s['SidebarDesc'])],[Paragraph('10–12 · VALIDACIÓN',s['SidebarItem']),Paragraph('Qué falló, qué aprendimos y qué mejoramos',s['SidebarDesc'])]]
st=Table(sidebar,colWidths=[68*mm,83*mm]); st.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NOCHE),('BACKGROUND',(0,1),(-1,-1),CARBON),('GRID',(0,0),(-1,-1),0.5,colors.HexColor('#56615F')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9)])); story += [st,Spacer(1,12*mm),Paragraph('Regla de separación',s['H2FP']),Paragraph('El informe explica las decisiones; las páginas de prototipo muestran la experiencia. No mezclen texto teórico dentro de las pantallas finales.',s['BodyFP']),Paragraph('Orden sugerido dentro de cada producto',s['H2FP'])]
flow=Table([[Paragraph('WEB',s['CenterSmall']),Paragraph('TÓTEM',s['CenterSmall'])],[Paragraph('01 Inicio<br/>02 Qué es FAIR PLAY<br/>03 Recorrido<br/>04 Zonas<br/>05 Información práctica<br/>06 Reservar / asistir',s['BodyFP']),Paragraph('01 Bienvenida<br/>02 Escanear o ingresar pasaporte<br/>03 Ver progreso<br/>04 Elegir estación<br/>05 Orientación / ayuda<br/>06 Confirmación',s['BodyFP'])]],colWidths=[75*mm,75*mm]); flow.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),SALVIA),('TEXTCOLOR',(0,0),(-1,0),PAPEL),('GRID',(0,0),(-1,-1),0.4,colors.HexColor('#B8C4BE')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9)])); story += [flow,PageBreak()]
story += [Paragraph('Checklist antes de entregar',s['H1FP'])]
for i,x in enumerate(['Cada página tiene un nombre y número consistente.','Los tres flows muestran inicio, acciones, decisiones y final.','Web y tótem comparten identidad, pero resuelven necesidades distintas.','El tótem contempla botones grandes, lectura a distancia, contraste, tiempo de interacción y alternativa sin QR.','La web funciona sin depender de una explicación oral del equipo.','El UI Kit documenta estados: default, hover, focus, pressed, disabled y error.','Las heurísticas tienen evidencia concreta y severidad priorizada.','Los testeos incluyen tareas observables, no solo opiniones generales.','La iteración final muestra qué cambió a partir de los resultados.'],1): story.append(Paragraph(f'{i:02d}  {x}',s['BodyFP']))
story += [Spacer(1,8*mm),Paragraph('Decisión central para FAIR PLAY',s['H2FP']),Paragraph('La interfaz debe invitar a entrar por el espectáculo y acompañar a descubrir lo que el espectáculo oculta. Esa transición tiene que sentirse tanto en el contenido como en el orden visual de las pantallas.',s['BodyFP'])]
doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=18*mm,bottomMargin=20*mm,title='FAIR PLAY TP3 - Estructura de sidebar'); doc.build(story,onFirstPage=cover,onLaterPages=footer); print(OUT)
